import 'package:flutter_test/flutter_test.dart';

import 'package:submersion/features/safety/data/services/emergency_data_service.dart';
import 'package:submersion/features/safety/domain/entities/emergency_info.dart';

/// Invariants over the shipped chamber asset. These guard a safety-critical
/// dataset that is regenerated by `scripts/chamber_harvester.py`: a parser that
/// silently starts emitting empty phone numbers or duplicate ids fails here
/// rather than on a diver's phone.
void main() {
  TestWidgetsFlutterBinding.ensureInitialized();

  setUp(EmergencyDataService.resetCacheForTesting);

  test('every chamber row satisfies the dataset invariants', () async {
    final chambers = await EmergencyDataService.loadBundledChambers();
    expect(chambers, isNotEmpty);

    final seenIds = <String>{};
    for (final chamber in chambers) {
      final where = '${chamber.id} (${chamber.name})';

      expect(seenIds.add(chamber.id), isTrue, reason: 'duplicate id: $where');
      expect(chamber.name.trim(), isNotEmpty, reason: 'blank name: $where');
      expect(
        chamber.country,
        matches(RegExp(r'^[A-Z]{2}$')),
        reason: 'country must be an ISO 3166-1 alpha-2 code: $where',
      );
      expect(chamber.phone.trim(), isNotEmpty, reason: 'blank phone: $where');
      expect(
        chamber.phone,
        startsWith('+'),
        reason: 'phone must be internationally dialable: $where',
      );
      expect(
        chamber.isBuiltIn,
        isTrue,
        reason: 'bundled rows are built in: $where',
      );
      expect(
        chamber.lastVerified,
        isNotNull,
        reason: 'no verification date: $where',
      );
    }
  });

  test('coordinates are present and on the planet', () async {
    final chambers = await EmergencyDataService.loadBundledChambers();

    for (final chamber in chambers) {
      final where = '${chamber.id} (${chamber.name})';
      expect(chamber.latitude, isNotNull, reason: 'no latitude: $where');
      expect(chamber.longitude, isNotNull, reason: 'no longitude: $where');
      expect(chamber.latitude!, inInclusiveRange(-90, 90), reason: where);
      expect(chamber.longitude!, inInclusiveRange(-180, 180), reason: where);
      // 0,0 is in the Gulf of Guinea and is what a failed geocode looks like.
      expect(
        chamber.latitude == 0 && chamber.longitude == 0,
        isFalse,
        reason: 'null island coordinates: $where',
      );
    }
  });

  test('verification dates are not in the future', () async {
    final chambers = await EmergencyDataService.loadBundledChambers();
    final now = DateTime.now();

    for (final chamber in chambers) {
      expect(
        chamber.lastVerified!.isAfter(now),
        isFalse,
        reason: 'verified in the future: ${chamber.id}',
      );
    }
  });

  test('the ids users may have hidden are still present', () async {
    // `hiddenChamberIds` in settings stores raw ids. Renaming one of these
    // resurrects a chamber a user deliberately hid.
    const preserved = [
      'us-duke',
      'us-catalina',
      'au-townsville',
      'au-fionastanley',
      'nz-slark',
      'gb-ddrc',
      'mt-gozo',
      'eg-sharm',
      'ph-batangas',
      'id-bali',
      'mv-bandos',
      'mx-cozumel',
      'za-capetown',
    ];

    final chambers = await EmergencyDataService.loadBundledChambers();
    final ids = chambers.map((c) => c.id).toSet();

    for (final id in preserved) {
      expect(ids, contains(id), reason: 'id $id disappeared from the dataset');
    }
  });

  test('the dataset is a directory, not a sample', () async {
    // The 14-row placeholder that shipped before this dataset existed is what
    // this floor exists to prevent recurring. Raise it as coverage grows.
    final chambers = await EmergencyDataService.loadBundledChambers();

    expect(chambers.length, greaterThanOrEqualTo(100));
  });

  test('coverage is not concentrated in a single country', () async {
    final chambers = await EmergencyDataService.loadBundledChambers();
    final countries = chambers.map((c) => c.country).toSet();

    expect(countries.length, greaterThanOrEqualTo(20));
    // North America had no reachable aggregator (UHMS is bot-blocked, DAN
    // publishes nothing), so it was assembled facility by facility and is the
    // coverage most likely to regress silently.
    expect(countries, contains('US'));
    expect(countries, contains('CA'));
  });

  test('the directory carries its provenance', () async {
    final chambers = await EmergencyDataService.loadBundledChambers();

    // No source publishes this data under a redistribution license, so every
    // row has to stand on its own citation.
    for (final chamber in chambers) {
      expect(
        chamber.verifiedUrl,
        isNotNull,
        reason: 'no source URL: ${chamber.id}',
      );
      expect(
        chamber.verifiedVia,
        isNot(ChamberVerification.unknown),
        reason: 'unclassified provenance: ${chamber.id}',
      );
    }
  });

  test('the Benelux hyperbaric centres are all present', () async {
    // Issue #1521: the directory carried one chamber for Belgium and one for
    // the Netherlands, so a diver in Flanders was shown a facility hours away
    // while the centre in the next town was missing. ACHOBEL and the NVvHG
    // both publish a national list; every centre on them that could be
    // confirmed against its own hospital is in the dataset.
    final chambers = await EmergencyDataService.loadBundledChambers();
    final ids = chambers.map((c) => c.id).toSet();

    const belgium = [
      'be-aalst',
      'be-antwerpen',
      'be-brugge',
      'be-brussels',
      'be-genk',
    ];
    const netherlands = [
      'nl-amsterdam',
      'nl-goes',
      'nl-sneek',
      'nl-denhelder',
      'nl-rijswijk',
    ];

    for (final id in [...belgium, ...netherlands, 'lu-esch']) {
      expect(ids, contains(id), reason: 'missing Benelux chamber: $id');
    }
  });

  test('the Benelux acute chambers are reachable around the clock', () async {
    // The whole point of listing these is the 3am call. A row that lands in
    // the diving_emergency band without an availability to match is a row
    // nobody checked.
    final chambers = await EmergencyDataService.loadBundledChambers();

    for (final chamber in chambers.where(
      (c) => c.country == 'BE' || c.country == 'NL' || c.country == 'LU',
    )) {
      if (chamber.capability != ChamberCapability.divingEmergency) continue;
      expect(
        chamber.availability,
        ChamberAvailability.h24,
        reason: 'acute chamber without 24h cover: ${chamber.id}',
      );
    }
  });

  test('the suspended Charleroi chamber stays out of the dataset', () async {
    // CHU de Charleroi (HUmani) suspended the Hopital Andre Vesale caisson on
    // 2026-06-25, the last multiplace chamber in Wallonia, over the cost of
    // the safety refit. It is still on the ACHOBEL member list, which is why
    // this guard exists: the list is a lead, not the truth, and sending a bent
    // diver to a chamber that cannot pressurise costs them the time that
    // matters most.
    final chambers = await EmergencyDataService.loadBundledChambers();

    expect(chambers.map((c) => c.id), isNot(contains('be-charleroi')));
  });

  test('the Koh Samui chamber stays out of the dataset', () async {
    // `th-samui` shipped in the placeholder dataset, and this is the one
    // preserved id deliberately dropped rather than carried across. The SSS
    // Chamber Network's own site lists exactly two Thai locations, Koh Tao and
    // Phuket; the only Samui page still reachable carries a 2010 copyright.
    // A chamber that has closed is worse than a gap, because a diver calling a
    // dead number loses the time they most need.
    final chambers = await EmergencyDataService.loadBundledChambers();

    expect(chambers.map((c) => c.id), isNot(contains('th-samui')));
  });
}
